fn maybe_add(
    items: &[Arc<Workspace>],
    vfs: &dyn VfsHandler,
    scheme: Scheme,
    root: Arc<NormalizedPath>,
    kind: WorkspaceKind,
) -> Option<Arc<Workspace>> {
    if items.iter().any(|item| item.root_path == root) {
        // The path is already in there
        return None;
    }
    let workspace = Workspace::new(vfs, &*items, scheme, root, kind);
    Some(workspace)
}

